HW = 'Hugo Wolff'
E = {}
E['ritual-si-mere-rosii'] = dict(title='Ritual and Red Apples', h1='Ritual and<br>Red Apples', orig='Ritual și Mere Roșii',
  eyebrow='Current production', subtitle='or what might have been a Greek tragedy',
  credits=[('Choreography','Alex Wolff'),('Genre','Contemporary theatre dance'),('Premiere','9 October 2025, “Ion Besoiu” Cultural Centre')],
  card='Choreography: Alex Wolff. A collective confession about conformity, guilt and liberation.',
  about=['You do not sin because you wanted to. You sin because you were told that you should. Because that is what you saw others do. Because in a society that confuses conformity with virtue, refusal becomes the ultimate sin.',
   'Society does not push you; it simply offers you an apple, with the gentle smile of those who have already taken a bite, and whispers: it’s time. Everyone has tasted it. Everyone says it’s natural. What is the point of resisting, when resistance means isolation?',
   'On stage, bodies speak about what we are afraid to admit: the fear of being different, the need to be loved at any cost, the exhaustion of pretending you are fine, the shame of feeling.',
   'The performance is a collective confession, a circle in which guilt becomes dance, and dance becomes a form of survival. A ritual about how we end up living other people’s lives, hiding our own desires in the pockets of shame.',
   'It is a story about how sin becomes tradition. About how, over time, mistakes are no longer condemned — they are repeated, learned, inherited. And in the end, when the taste of the apple clings to the roof of your mouth and you no longer know whether it is sweet or bitter, one unavoidable question remains:',
   'Was it your choice? Or merely one step in an old dance, repeated endlessly, with your eyes closed?'],
  context=['“Ritual and Red Apples” opened the second edition of the “Hugo Wolff” Dance Festival before a full house, on 9 October 2025, at the “Ion Besoiu” Cultural Centre in Sibiu — a festival organised by the University Cultural Center of Sibiu in memory of the company’s founder. The local press described the evening as “a memorable opening”, a performance that “impressed with its intensity, constant energy and powerful symbols”.'],
  team=[('Choreography','Alex Wolff'),('Assistant choreographer','Raluca-Sânziana Cristea'),('Assistant director','Florian Oros'),('Rehearsal directors','Diana-Elena Cătănescu, Eleni-Alexandra Popa'),('Costumes','Ana-Daniela Drăgan')])
E['clipe-de-luciditate'] = dict(title='Moments of Awareness', h1='Moments of<br>Awareness', orig='Clipe de luciditate',
  eyebrow='Reinterpretation', subtitle='adaptation after a choreography by Hugo Wolff',
  credits=[('Choreography',HW),('Direction','Florian Oros'),('Presented at','Serbările Unirii, Alba Iulia · 27 Nov. 2024')],
  card='Directed by Florian Oros, after Hugo Wolff’s choreography. Thirteen people in a sanatorium, in the moments when the masks fall.',
  about=['Moments of Awareness is an intimate and profound performance that reveals the inner universe of 13 people brought together in a sanatorium, each with their own suffering hidden behind a mask. In this isolated place, where time seems suspended, each character experiences moments of lucidity in which their past and traumas come to the surface.',
   'Throughout the performance, we glimpse fragments of life: characters with stories that have marked their existence and that unfold like an emotional puzzle, revealing the personal drama that brought them to this place of pain.',
   'As they coexist in this place of suffering, the characters discover that, although they hide their wounds, they are bound by a common desire for healing and understanding. In these moments of lucidity, barriers break, “masks fall”, and the performance takes us on a journey through trauma and human fragility, to a place where no one would want to go, but which, paradoxically, reveals universal truths about loss, acceptance and hope.',
   'The performance explores human vulnerability and the complexity of relationships, in a symbolic setting that reflects the tension between suffering and the desire for liberation.'],
  context=['Moments of Awareness was first created in 1993 by Hugo Wolff as one of the early contemporary dance works of the MICROBIS Theatre Dance Company. In its present reimagining, under the direction of Florian Oros, the original themes and choreography remain faithful to the original creation, while new layers of psychological depth emerge. Through deeply personal contributions from the dancers, the performance gains renewed intensity, becoming a living dialogue between past and present.',
   'The performance was presented on 27 November 2024 at the University Cultural Center of Alba Iulia, as part of the 28th edition of the “Serbările Unirii” National Student Festival.'],
  related=('clipe-de-luciditate-1997','See the original version'),
  musicians=['Petru Adam – trumpet','Carina Cataramă – pan flute','Liviu Cernat – violin','Ovidiu Pârjol – piano','Claudiu Leș – guitar','Nicolaie Beșleagă – keyboards','Dominique Simionescu – vocals','Gheorghe Berghian Gino – vocals'],
  team=[('Choreography',HW),('Direction','Florian Oros'),('Music','Expert G Entertainment &amp; Moving Records')])
E['tinerete-fara-batranete'] = dict(title='Youth Without Age', h1='Youth<br>Without Age', orig='Tinerețe fără bătrânețe',
  eyebrow='Anniversary performance · Microbis at 30', subtitle='The last choreography Hugo Wolff created for the company he founded.',
  credits=[('Direction &amp; choreography',HW),('Occasion','“Microbis – 30 Years” anniversary'),('Year','2023')],
  card='Directed and choreographed by Hugo Wolff. The “Microbis – 30 Years” anniversary performance.',
  about=['Conceived as a synthesis of thirty years of creation, the performance explores the dance of death and the cycle of human life through a “doubled” character — one side of whose costume bears a human skeleton. The local press described the creative process as one of rare intensity, with Hugo Wolff himself being, at the time, “in a veritable creative trance”.'],
  context=['“Youth Without Age” was conceived to mark three decades since the company was founded. Shortly after this anniversary, Hugo Wolff died suddenly, on the night of 27 to 28 August 2023 — and the performance has remained, in retrospect, his artistic testament.'],
  team=[('Direction and choreography',HW)])
E['romeo-si-julieta'] = dict(title='Romeo and Juliet', h1='Romeo and Juliet', orig='Romeo și Julieta',
  eyebrow='Choreographic theatre', subtitle='after William Shakespeare',
  credits=[('Choreography, set and costumes',HW),('Genre','Choreographic theatre'),('Year','2019')],
  card='Choreography: Hugo Wolff, after William Shakespeare. The story of the two lovers, moved to an asylum.',
  about=['Romeo and Juliet, or “the most beautiful and tragic love story of all time”, becomes in this adaptation a universe where words lose their intensity and are replaced by raw emotion. The main ingredient of this prescription is love — perhaps the most youthful and reckless component of human existence. Love makes you noble, yet it can just as easily stain you. Because of love we smile or suffer, we dream or fall, we are blinded by happiness or driven mad by restlessness. Its dosage is contagious; it can happen to anyone, at any time. Surely there must be a place where all these contradictory states coexist in harmony.',
   'This time, we are not in Verona, but in an asylum, where reason dissolves and authentic feelings overwhelm the individual. In the white room, life is rewritten at maximum intensity: ecstatic joy collides with past dramas shaped by the outside world of rivalry, conflict and social status. In this world, two young people look at each other naively and fall instantly in love. A sweet cocktail of eroticism and desire floods their minds and souls — but when love meets impossibility, reason collapses. Emotional pain is amplified in confinement, and maintaining psychological balance becomes as impossible as walking a tightrope made of barbed wire.',
   'The feelings and inner turmoil of the two lovers are carried by music and rhythm. There are moments when the lines of the body, the energy of movement, the abstract and the concrete merge, dissolving the need for words and creating a sea of images and messages charged with unsettling emotion. Storms of action and continuous waves of feeling follow one another on stage until, at last, silence descends. A painful silence. Love reveals itself as the most beautiful of feelings and the only one still capable of healing us — as individuals, as a collective, as a society. It is the only force that can mend us and bring us back — together.'],
  context=['The performance was presented by the Microbis Association and the MICROBIS Theatre Dance Company, in partnership with the University Cultural Center of Sibiu.'],
  team=[('Choreography, set and costumes',HW),('Lighting','Radu Drusan'),('Technical director','Horea Suciu'),('Sound','Dan Caras')])
E['fetita-cu-chibrituri'] = dict(title='The Little Match Girl', h1='The Little<br>Match Girl', orig='Fetița cu chibrituri',
  eyebrow='Theatre dance', subtitle='after Hans Christian Andersen',
  credits=[('Direction &amp; choreography',HW),('Genre','Theatre dance'),('Year','2018')],
  card='Directed and choreographed by Hugo Wolff, after Hans Christian Andersen. The fairy tale told through primal, visceral gesture.',
  about=['In a society that leaves its children to grow up alone, exploitation is only one step away. This story is more painfully current than we would like it to be: every human being and every creature deprived of warmth, both physical and emotional, is a “Little Match Girl” who will surely perish in the end.',
   'We chose to tell this story through movement — the primal, visceral gesture that can sometimes matter more than the spoken word, even though Andersen’s genius cannot be ignored. While in our youth everyone knew “The Little Match Girl”, the story of the girl forced by her father to sell matches to survive, children today are more likely to know the latest computer game on the market than this literary masterpiece.',
   'The girl is cold, barefoot and poor — without a friend in the world — but not without hope. She dreams of warmth and light, of a time when she will be surrounded by love and filled with happiness. These dreams lie so far beyond her lived experience that others would long since have given them up. But she does not give up hope.',
   'Still, the harsh realities of poverty haunt her: she must sell matches for fear of being beaten by her father when she returns home, and this fear keeps her outside all night, which ultimately leads to her death.',
   'We may not think about the horrible things that happen every day, and they are hard to explain to our children. It seems, however, that we can often learn the greatest lessons from children — from the way they manage to face the most uncertain situations.',
   'In those final moments, this little girl sees visions of splendour. She sees hope. But her death — marked by a star falling across the dark sky — is tragic and disturbing.',
   'The girl is a symbol of the countless nameless people who suffer and die in poverty every year and remain unnoticed. This is not merely a sad story but a reality check for us all. We must be grateful for everything we have and generous to those in need.',
   'It may seem old-fashioned to try to show, through a fairy tale, all the crises of today’s society and to call them out through a secular ritual of theatre dance on a modern stage, for an audience held permanently captive by technology and the virtual world. But for us, the feelings and gestures of the characters matter more than all existing holograms and software. That is why we take up the wager with the divine, seeking to prove that human relationships, compassion and the highest ideals are not illusions controlled by satellite or drone, but tangible, real things — all the more necessary for a healthy, civilised society.'],
  context=['A production of the University Cultural Center of Sibiu.'],
  team=[('Direction and choreography',HW)])
E['colectionarul'] = dict(title='The Collector', h1='The Collector', orig='Colecționarul',
  eyebrow='Theatre dance', subtitle='after a novel by John Fowles',
  credits=[('Direction &amp; choreography',HW),('Genre','Theatre dance'),('Year','2017')],
  card='Directed and choreographed by Hugo Wolff, after a novel by John Fowles. A man who “collects” women falls into his own trap.',
  about=['The performance tells the story of a man who ages physically but remains psychologically powerful — and from this comes his power to manipulate the world, especially women. His supreme pleasure is to “collect” women of different races, shapes, ages, types and personalities, whom he uses in his own Machiavellian way. At some point he drives them to suicide or even kills them, to vary his pleasures. He reaches the heights of human perversity, in defiance of the dogmas imposed by society.',
   'But one day he meets someone who unsettles him. She withstands every challenge because she has built several personalities that she can abandon or return to at will. She can also switch between them instinctively whenever he attacks her. Trying to control her, he falls into his own trap and becomes dependent on her love.',
   'He himself ends up ready to give up everything, even his life, just to be noticed and loved by her. His obsession with becoming whole turns manic. After a spiritually and physically perfect relationship, leading to ancestral, almost fantastical discoveries, an utterly trivial event makes her realise his true intentions — and when she understands that she cannot bring him back to reality, she decides that he must die, not her. How will all of this come about?'],
  context=['Producer: University Cultural Center of Sibiu, MICROBIS Theatre Dance Company.'],
  team=[('Direction and choreography',HW)])
E['bonnie-clyde'] = dict(title='Bonnie &amp; Clyde', h1='Bonnie &amp; Clyde', orig='',
  eyebrow='Theatre dance', subtitle='',
  credits=[('Direction &amp; choreography',HW),('Genre','Theatre dance'),('Year','2016')],
  card='Directed and choreographed by Hugo Wolff. The story of the 1930s outlaw couple, told through dance.',
  about=['Told through dance, the story of Bonnie and Clyde unfolds the web of relationships of the 1930s, the era of public enemies and of outlaws whose crimes made history. Love and robberies: a fascinating, moving story that has captivated the whole world.',
   '“Bonnie and Clyde” is a performance built around love — a youthful, passionate love, full of adventure and eroticism. Choreographer Hugo Wolff brings out a violent, at times degrading universe that nonetheless explodes into a rare tenderness: the sensitive image of the deep layer born from the pain of childhood trauma.',
   'The story, the choreographic discourse, the props and the staging firmly reject the idea of immaculate white and absolute black, convincing the audience that innocence is not what it seems: it can be lost in a moment of terrible pain and regained just as quickly, with the help of the supreme feeling — Love.'],
  context=['Producer: University Cultural Center of Sibiu.'],
  team=[('Direction and choreography',HW)])
E['damnatul'] = dict(title='The Damned', h1='The Damned', orig='Damnatul',
  eyebrow='Theatre dance', subtitle='“Do not forget!”',
  credits=[('Direction &amp; choreography',HW),('Stage design','Mc Ranin'),('Year','2014')],
  card='Directed and choreographed by Hugo Wolff. Two worlds — of vampires and of mortals — and a love that knows no limits.',
  about=['“The Damned”, the new production of the Microbis dance company, directed and choreographed by Hugo Wolff, portrays humanity in all its complexity: a being that oscillates between contradictory states — happiness, fulfilment and love, pain, despair and resignation.',
   'Two worlds take shape in the performance: the eternal world of vampires and the limited world of mortals. The story unfolds in several scenes, each supported by musical fragments specific to the moment portrayed. At first, the vampires — creatures thousands of years old — seek out mortals to turn them into vampires. Then the ritual of a mortal’s transformation is shown. The journey is rendered through slow movements, with pain conveyed through facial expression.',
   'In another scene, the dance of two mortals is passionate and full of sensuality, sketching the love that envelops them. The vampires’ intervention, however, proves fatal for the lovers: the man is caught and turned into a vampire. The ritual on the cross is symbolic and leads towards “prehistoric times”, suggesting resurrection. The man becomes eternal, but he is punished: he can know love only as long as the woman lives. He finds his beloved again in another historical moment and in another guise, but lacks the strength to carry her into eternity.',
   '“The Damned” thus depicts suffering — man’s punishment of remaining alone, isolated, thirsting to find his ideal. At the same time, this theatre dance performance brings out the idea that love has no limits: the feeling can exist between vampires, between mortals, or between vampires and mortals. In the end we are left with a question: is it better to live forever but know true happiness only for a short while, or to be mortal and enjoy the happiness offered by one’s ideal partner for the rest of one’s life?'],
  context=['Producer: University Cultural Center of Sibiu.'],
  team=[('Direction and choreography',HW),('Stage design','Mc Ranin')])
Q_CURTEA1 = ('Quite transparently, and all the more appreciated by the audience, the questions, dramas and many problems of youth became visible in the performance ‘The Court of Miracles’, a modern journey through contemporary life in which a young person finds himself with difficulty, and his guardian angel only rarely…', 'Victoria A.F., Monitorul de Brăila, June 2005')
Q_CURTEA2 = ('The 10 members of the group, together with Hugo, succeeded in staging an impossible love story from the 19th century, when differences in social rank were an insurmountable obstacle for two lovers. This story of a ‘he’ and a ‘she’ is transferred to the 20th century, when social rank no longer matters, but when a greater danger threatens a relationship: drugs — the young people’s dance being a protest against this scourge.', '(A.C.) Monitorul de Brăila, 4–5 June 2005')
