E['hurem-conditia-umana'] = dict(title='Hurem — The Human Condition', h1='Hurem', orig='Hurem — condiția umană',
  eyebrow='Theatre dance', subtitle='The Human Condition',
  credits=[('Choreographer',HW),('Genre','Theatre dance'),('Year','2012')],
  card='A theatre dance performance, choreographer Hugo Wolff.',
  about=[], context=['A theatre dance performance. Choreographer: Hugo Wolff. Producer: University Cultural Center of Sibiu, MICROBIS Theatre Dance Company.'],
  quotes=[('The performance ‘HUREM – The Human Condition’ has the cycle of human life as its common thread, each stage we pass through being clearly transposed into the choreographic discourse. With relatively simple props, but with choreography built on extremely varied and coherent movement, choreographer Hugo Wolff manages to bring out every age of human life, leaving no room for misinterpretation. The stories are told through dance, music, poetry and, not least, through the unconventional space chosen for the premiere.', 'Tribuna, 19 September 2012 — “Hurem, a dancing premiere”')],
  team=[])
E['ultima-imbucatura-din-dragoste'] = dict(title='The Last Bite of… Love', h1='The Last Bite<br>of… Love', orig='Ultima îmbucătură din... dragoste',
  eyebrow='Theatre dance', subtitle='',
  credits=[('Genre','Theatre dance'),('Producer','University Cultural Center of Sibiu'),('Year','2011')],
  card='A theatre dance performance by the MICROBIS Theatre Dance Company.',
  about=[], context=['A theatre dance performance. Producer: University Cultural Center of Sibiu, MICROBIS Theatre Dance Company. Poster design: Mihai Panaitescu.'],
  quotes=[('Starting from historical scenes, Hugo Wolff, who created the choreography for this performance, has transposed into dance moments from the dark history of Europe. The MICROBIS Dance Company presents a creation set in a ‘death camp’, a story of love and hate told through dance and music. The MICROBIS Dance Company supports and promotes mainly contemporary dance, with the aim of initiating high-impact cultural projects. Although made up mostly of students, the Microbis Company has managed over the years to impress with its original choreographic productions.', 'Adevărul de seară, 4 October 2011')],
  team=[])
