E['clipe-de-luciditate-1997'] = dict(title='Moments of Awareness (original version)', h1='Moments of<br>Awareness', orig='Clipe de luciditate', plain='Moments of Awareness',
  eyebrow='Original version', subtitle='a performance by Hugo Wolff',
  credits=[('A performance by',HW),('Genre','Theatre dance'),('First created','1993')],
  card='A performance by Hugo Wolff — one of the company’s first contemporary dance works.',
  about=[], context=['Moments of Awareness was first created in 1993 by Hugo Wolff as one of the early contemporary dance works of the MICROBIS Theatre Dance Company. Blending traditional elements with the intense expressiveness of contemporary movement, the performance explored the fragile boundary between lucidity and madness.',
   'The archive poster bears the heading of the Ministry of Education and of the Sibiu Student Culture House, and presents “Moments of Awareness” (Clipe de luciditate) as “a performance by Hugo Wolff”.'],
  related=('clipe-de-luciditate','See the 2024 reinterpretation'),
  quotes=[('The appearance of the madmen in <em>Moments of Awareness</em> brings to mind the madmen of <em>The Seventh Commandment</em> by Dario Fo — characters who have moments of lucidity in a life where people struggle to survive, and who are often the most lucid of all. The artistic interpretation was interesting: a performance with well-crafted stage design and rich stage movement. A hard-worked performance, as choreographer Hugo Wolff confesses: <em>We worked on this performance for six months.</em> Their inner turmoil, transformed into movement and grace, every feeling translated into undulations and steps and conveyed directly to the audience, creates a communion between character and performer.', 'Liviu Pietraru, Rondul de Sibiu, 22 April 1997')],
  team=[])
